#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""10-biyoloji-14 özel vektörel görselleri (6 bölüm, zengin SVG)."""

GORSELLER = {'b1': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">BESİNLERİN OKSİJENLİ SOLUNUMA KATILMA YOLLARI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#2563eb">MONOMERLERE SİNDİRİM (HİDROLİZ)</text>\n  <text x="34" y="88" font-size="11" fill="#1e3a8a">• Polisakkaritler (Nişasta, Glikojen) -&gt; Glikoz (6C)</text>\n  <text x="34" y="112" font-size="11" fill="#1e3a8a">• Nötral Yağlar (Trigliserit) -&gt; Gliserol (3C) + 3 Yağ Asidi</text>\n  <text x="34" y="136" font-size="11" fill="#1e3a8a">• Proteinler -&gt; Amino Asitler (deaminasyonla NH3 ayrılır)</text>\n  <text x="34" y="160" font-size="11" fill="#1e3a8a">• Sindirimde ATP üretilmez ve ATP harcanmaz!</text>\n  <text x="34" y="184" font-size="11" fill="#1e3a8a">• Oluşan monomerler kanla hücrelere taşınır</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#059669">SOLUNUMA KATILIM BASAMAKLARI</text>\n  <text x="370" y="88" font-size="11" fill="#064e3b">• Glikoz (6C) -&gt; Doğrudan Glikoliz evresinden katılır</text>\n  <text x="370" y="112" font-size="11" fill="#064e3b">• Gliserol (3C) -&gt; Glikoliz ara basamağından (PGAL) katılır</text>\n  <text x="370" y="136" font-size="11" fill="#064e3b">• Yağ Asitleri (2C) -&gt; Beta oksidasyonla Asetil-CoA\'dan katılır</text>\n  <text x="370" y="160" font-size="11" fill="#064e3b">• Amino Asitler -&gt; Karbon sayısına göre (3C Pirüvat,</text>\n  <text x="370" y="184" font-size="11" fill="#064e3b">• 2C Asetil-CoA veya 4C-5C Sitrik Asit Döngüsü) katılır</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Bütün organik besin monomerlerinin hücresel solunumda ortak buluşma kavşağı Asetil-CoA ve Sitrik Asit Döngüsüdür.</text>\n</svg>', '1': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">BESİNLERİN OKSİJENLİ SOLUNUMA KATILMA YOLLARI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#2563eb">MONOMERLERE SİNDİRİM (HİDROLİZ)</text>\n  <text x="34" y="88" font-size="11" fill="#1e3a8a">• Polisakkaritler (Nişasta, Glikojen) -&gt; Glikoz (6C)</text>\n  <text x="34" y="112" font-size="11" fill="#1e3a8a">• Nötral Yağlar (Trigliserit) -&gt; Gliserol (3C) + 3 Yağ Asidi</text>\n  <text x="34" y="136" font-size="11" fill="#1e3a8a">• Proteinler -&gt; Amino Asitler (deaminasyonla NH3 ayrılır)</text>\n  <text x="34" y="160" font-size="11" fill="#1e3a8a">• Sindirimde ATP üretilmez ve ATP harcanmaz!</text>\n  <text x="34" y="184" font-size="11" fill="#1e3a8a">• Oluşan monomerler kanla hücrelere taşınır</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#059669">SOLUNUMA KATILIM BASAMAKLARI</text>\n  <text x="370" y="88" font-size="11" fill="#064e3b">• Glikoz (6C) -&gt; Doğrudan Glikoliz evresinden katılır</text>\n  <text x="370" y="112" font-size="11" fill="#064e3b">• Gliserol (3C) -&gt; Glikoliz ara basamağından (PGAL) katılır</text>\n  <text x="370" y="136" font-size="11" fill="#064e3b">• Yağ Asitleri (2C) -&gt; Beta oksidasyonla Asetil-CoA\'dan katılır</text>\n  <text x="370" y="160" font-size="11" fill="#064e3b">• Amino Asitler -&gt; Karbon sayısına göre (3C Pirüvat,</text>\n  <text x="370" y="184" font-size="11" fill="#064e3b">• 2C Asetil-CoA veya 4C-5C Sitrik Asit Döngüsü) katılır</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Bütün organik besin monomerlerinin hücresel solunumda ortak buluşma kavşağı Asetil-CoA ve Sitrik Asit Döngüsüdür.</text>\n</svg>', 'b2': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">AMİNO ASİTLERİN DEAMİNASYONU VE BESİNLERİN ENERJİ VERİMİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#f5f3ff" stroke="#7c3aed" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#7c3aed">DEAMİNASYON (AMONYAK ÇIKIŞI)</text>\n  <text x="34" y="88" font-size="11" fill="#4c1d95">• Amino asitlerde C, H, O yanında Azot (N) atomu bulunur</text>\n  <text x="34" y="112" font-size="11" fill="#4c1d95">• Solunuma katılmadan önce amino grubu (-NH2) koparılır</text>\n  <text x="34" y="136" font-size="11" fill="#4c1d95">• Bu olaya deaminasyon denir; NH3 (amonyak) açığa çıkar</text>\n  <text x="34" y="160" font-size="11" fill="#4c1d95">• İnsanda NH3 karaciğerde üreye çevrilip böbrekle atılır</text>\n  <text x="34" y="184" font-size="11" fill="#4c1d95">• Yalnız amino asit yıkımında NH3 ve üre artışı görülür!</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#d97706">1 GRAM BESİNİN ENERJİ DEĞERİ</text>\n  <text x="370" y="88" font-size="11" fill="#78350f">• 1. Yağlar: ~9,3 kcal/g (Bol H atomu -&gt; Çok NADH/FADH2)</text>\n  <text x="370" y="112" font-size="11" fill="#78350f">• 2. Proteinler: ~4,3 kcal/g</text>\n  <text x="370" y="136" font-size="11" fill="#78350f">• 3. Karbohidratlar: ~4,2 kcal/g</text>\n  <text x="370" y="160" font-size="11" fill="#78350f">• Açlıkta kullanım sırası: 1. Karbohidrat, 2. Yağ, 3. Protein</text>\n  <text x="370" y="184" font-size="11" fill="#78350f">• Yapıya katılma sırası: 1. Protein, 2. Yağ, 3. Karbohidrat</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Yağların birim ağırlıkta en çok ATP ve metabolik su vermesinin nedeni çok sayıda hidrojen atomu içermesidir.</text>\n</svg>', '2': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">AMİNO ASİTLERİN DEAMİNASYONU VE BESİNLERİN ENERJİ VERİMİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#f5f3ff" stroke="#7c3aed" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#7c3aed">DEAMİNASYON (AMONYAK ÇIKIŞI)</text>\n  <text x="34" y="88" font-size="11" fill="#4c1d95">• Amino asitlerde C, H, O yanında Azot (N) atomu bulunur</text>\n  <text x="34" y="112" font-size="11" fill="#4c1d95">• Solunuma katılmadan önce amino grubu (-NH2) koparılır</text>\n  <text x="34" y="136" font-size="11" fill="#4c1d95">• Bu olaya deaminasyon denir; NH3 (amonyak) açığa çıkar</text>\n  <text x="34" y="160" font-size="11" fill="#4c1d95">• İnsanda NH3 karaciğerde üreye çevrilip böbrekle atılır</text>\n  <text x="34" y="184" font-size="11" fill="#4c1d95">• Yalnız amino asit yıkımında NH3 ve üre artışı görülür!</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#d97706">1 GRAM BESİNİN ENERJİ DEĞERİ</text>\n  <text x="370" y="88" font-size="11" fill="#78350f">• 1. Yağlar: ~9,3 kcal/g (Bol H atomu -&gt; Çok NADH/FADH2)</text>\n  <text x="370" y="112" font-size="11" fill="#78350f">• 2. Proteinler: ~4,3 kcal/g</text>\n  <text x="370" y="136" font-size="11" fill="#78350f">• 3. Karbohidratlar: ~4,2 kcal/g</text>\n  <text x="370" y="160" font-size="11" fill="#78350f">• Açlıkta kullanım sırası: 1. Karbohidrat, 2. Yağ, 3. Protein</text>\n  <text x="370" y="184" font-size="11" fill="#78350f">• Yapıya katılma sırası: 1. Protein, 2. Yağ, 3. Karbohidrat</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Yağların birim ağırlıkta en çok ATP ve metabolik su vermesinin nedeni çok sayıda hidrojen atomu içermesidir.</text>\n</svg>', 'b3': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">FERMANTASYONUN GENEL MEKANİZMASI: GLİKOLİZ VE SON ÜRÜN</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#059669">1. EVRE: GLİKOLİZ (SİTOPLAZMA)</text>\n  <text x="34" y="88" font-size="11" fill="#064e3b">• Glikoz (6C) -&gt; 2 Pirüvat (3C)</text>\n  <text x="34" y="112" font-size="11" fill="#064e3b">• Harcanan: 2 ATP (aktifleşme enerjisi)</text>\n  <text x="34" y="136" font-size="11" fill="#064e3b">• Üretilen: 4 ATP (Substrat Düzeyinde Fosforilasyon - SDF)</text>\n  <text x="34" y="160" font-size="11" fill="#064e3b">• Net kazanç: 2 ATP ve 2 NADH</text>\n  <text x="34" y="184" font-size="11" fill="#064e3b">• Tüm canlılarda ortak sitoplazmik enzimlerle yürür</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0f9ff" stroke="#0284c7" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#0284c7">2. EVRE: SON ÜRÜN OLUŞUMU</text>\n  <text x="370" y="88" font-size="11" fill="#0c4a6e">• Yeni ATP üretilmez ve ATP harcanmaz!</text>\n  <text x="370" y="112" font-size="11" fill="#0c4a6e">• Amaç: Glikolizde oluşan NADH\'ları tekrar NAD+ yapmak</text>\n  <text x="370" y="136" font-size="11" fill="#0c4a6e">• Böylece sitoplazmadaki NAD+ havuzu tükenmez</text>\n  <text x="370" y="160" font-size="11" fill="#0c4a6e">• Glikoliz kesintisiz devam ederek 2 ATP üretmeyi sürdürür</text>\n  <text x="370" y="184" font-size="11" fill="#0c4a6e">• Türe özgü farklı enzimler son ürün çeşidini belirler</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Fermantasyonda ETS görev almaz, oksijen kullanılmaz ve tüm tepkimeler sitoplazmada tamamlanır.</text>\n</svg>', '3': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">FERMANTASYONUN GENEL MEKANİZMASI: GLİKOLİZ VE SON ÜRÜN</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#059669">1. EVRE: GLİKOLİZ (SİTOPLAZMA)</text>\n  <text x="34" y="88" font-size="11" fill="#064e3b">• Glikoz (6C) -&gt; 2 Pirüvat (3C)</text>\n  <text x="34" y="112" font-size="11" fill="#064e3b">• Harcanan: 2 ATP (aktifleşme enerjisi)</text>\n  <text x="34" y="136" font-size="11" fill="#064e3b">• Üretilen: 4 ATP (Substrat Düzeyinde Fosforilasyon - SDF)</text>\n  <text x="34" y="160" font-size="11" fill="#064e3b">• Net kazanç: 2 ATP ve 2 NADH</text>\n  <text x="34" y="184" font-size="11" fill="#064e3b">• Tüm canlılarda ortak sitoplazmik enzimlerle yürür</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0f9ff" stroke="#0284c7" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#0284c7">2. EVRE: SON ÜRÜN OLUŞUMU</text>\n  <text x="370" y="88" font-size="11" fill="#0c4a6e">• Yeni ATP üretilmez ve ATP harcanmaz!</text>\n  <text x="370" y="112" font-size="11" fill="#0c4a6e">• Amaç: Glikolizde oluşan NADH\'ları tekrar NAD+ yapmak</text>\n  <text x="370" y="136" font-size="11" fill="#0c4a6e">• Böylece sitoplazmadaki NAD+ havuzu tükenmez</text>\n  <text x="370" y="160" font-size="11" fill="#0c4a6e">• Glikoliz kesintisiz devam ederek 2 ATP üretmeyi sürdürür</text>\n  <text x="370" y="184" font-size="11" fill="#0c4a6e">• Türe özgü farklı enzimler son ürün çeşidini belirler</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Fermantasyonda ETS görev almaz, oksijen kullanılmaz ve tüm tepkimeler sitoplazmada tamamlanır.</text>\n</svg>', 'b4': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">ETİL ALKOL VE LAKTİK ASİT FERMANTASYONU KARŞILAŞTIRMASI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#2563eb">ETİL ALKOL FERMANTASYONU</text>\n  <text x="34" y="88" font-size="11" fill="#1e3a8a">• 2 Pirüvat (3C) -&gt; 2 Asetaldehit (2C) + 2 CO2 gazı çıkışı</text>\n  <text x="34" y="112" font-size="11" fill="#1e3a8a">• 2 Asetaldehit + 2 NADH -&gt; 2 Etil Alkol (2C) + 2 NAD+</text>\n  <text x="34" y="136" font-size="11" fill="#1e3a8a">• Son elektron (hidrojen) alıcısı: Asetaldehit (2C)</text>\n  <text x="34" y="160" font-size="11" fill="#1e3a8a">• Kireç suyunu bulandıran CO2 çıkışı vardır</text>\n  <text x="34" y="184" font-size="11" fill="#1e3a8a">• Canlılar: Bira mayası mantarı, bazı bakteriler, bitki tohumu</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#dc2626">LAKTİK ASİT FERMANTASYONU</text>\n  <text x="370" y="88" font-size="11" fill="#7f1d1d">• 2 Pirüvat (3C) + 2 NADH -&gt; 2 Laktik Asit (3C) + 2 NAD+</text>\n  <text x="370" y="112" font-size="11" fill="#7f1d1d">• Karbondioksit (CO2) çıkışı GÖRÜLMEZ (3C -&gt; 3C)</text>\n  <text x="370" y="136" font-size="11" fill="#7f1d1d">• Son elektron (hidrojen) alıcısı: Doğrudan Pirüvat (3C)</text>\n  <text x="370" y="160" font-size="11" fill="#7f1d1d">• Tepkime kabında gaz basıncı değişmez, pH düşer</text>\n  <text x="370" y="184" font-size="11" fill="#7f1d1d">• Canlılar: Yoğurt bakterisi, olgun alyuvar, çizgili kas</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Etil alkol fermantasyonunda CO2 çıkışı varken laktik asit fermantasyonunda CO2 çıkışı yoktur.</text>\n</svg>', '4': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">ETİL ALKOL VE LAKTİK ASİT FERMANTASYONU KARŞILAŞTIRMASI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#2563eb">ETİL ALKOL FERMANTASYONU</text>\n  <text x="34" y="88" font-size="11" fill="#1e3a8a">• 2 Pirüvat (3C) -&gt; 2 Asetaldehit (2C) + 2 CO2 gazı çıkışı</text>\n  <text x="34" y="112" font-size="11" fill="#1e3a8a">• 2 Asetaldehit + 2 NADH -&gt; 2 Etil Alkol (2C) + 2 NAD+</text>\n  <text x="34" y="136" font-size="11" fill="#1e3a8a">• Son elektron (hidrojen) alıcısı: Asetaldehit (2C)</text>\n  <text x="34" y="160" font-size="11" fill="#1e3a8a">• Kireç suyunu bulandıran CO2 çıkışı vardır</text>\n  <text x="34" y="184" font-size="11" fill="#1e3a8a">• Canlılar: Bira mayası mantarı, bazı bakteriler, bitki tohumu</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#dc2626">LAKTİK ASİT FERMANTASYONU</text>\n  <text x="370" y="88" font-size="11" fill="#7f1d1d">• 2 Pirüvat (3C) + 2 NADH -&gt; 2 Laktik Asit (3C) + 2 NAD+</text>\n  <text x="370" y="112" font-size="11" fill="#7f1d1d">• Karbondioksit (CO2) çıkışı GÖRÜLMEZ (3C -&gt; 3C)</text>\n  <text x="370" y="136" font-size="11" fill="#7f1d1d">• Son elektron (hidrojen) alıcısı: Doğrudan Pirüvat (3C)</text>\n  <text x="370" y="160" font-size="11" fill="#7f1d1d">• Tepkime kabında gaz basıncı değişmez, pH düşer</text>\n  <text x="370" y="184" font-size="11" fill="#7f1d1d">• Canlılar: Yoğurt bakterisi, olgun alyuvar, çizgili kas</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Etil alkol fermantasyonunda CO2 çıkışı varken laktik asit fermantasyonunda CO2 çıkışı yoktur.</text>\n</svg>', 'b5': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">FERMANTASYON DENEY TASARIMI VE DEĞİŞKEN ANALİZİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#16a34a">MAYA MANTARI DENEY DÜZENEĞİ</text>\n  <text x="34" y="88" font-size="11" fill="#14532d">• A Kabı: Glikoz çözeltisi + Bira mayası + Ilık su (32 °C)</text>\n  <text x="34" y="112" font-size="11" fill="#14532d">• B Kabı: Gaz çıkış borusuyla bağlı Kireç suyu [Ca(OH)2]</text>\n  <text x="34" y="136" font-size="11" fill="#14532d">• Gözlem 1: A kabında glikoz azalır, etil alkol ve ısı artar</text>\n  <text x="34" y="160" font-size="11" fill="#14532d">• Gözlem 2: Çıkan CO2 gazı B kabındaki kireç suyunu bulandırır</text>\n  <text x="34" y="184" font-size="11" fill="#14532d">• Gözlem 3: Her iki kapta da pH değeri zamanla düşer</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#9333ea">KONTROLLÜ DENEY DEĞİŞKENLERİ</text>\n  <text x="370" y="88" font-size="11" fill="#581c87">• Bağımsız değişken: Araştırılan etken (örn. Sıcaklık)</text>\n  <text x="370" y="112" font-size="11" fill="#581c87">• Bağımlı değişken: Birim zamanda çıkan CO2 kabarcığı</text>\n  <text x="370" y="136" font-size="11" fill="#581c87">• Kontrol değişkenleri: Glikoz miktarı, su hacmi, maya</text>\n  <text x="370" y="160" font-size="11" fill="#581c87">• 60 °C üzerinde enzimler denatüre olur, tepkime durur</text>\n  <text x="370" y="184" font-size="11" fill="#581c87">• Alkol oranı %18\'i aşarsa maya hücreleri zehirlenir</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Termometredeki cıva seviyesinin yükselmesi hem solunumun hem fermantasyonun ekzergonik (ısı veren) olduğunu kanıtlar.</text>\n</svg>', '5': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">FERMANTASYON DENEY TASARIMI VE DEĞİŞKEN ANALİZİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#16a34a">MAYA MANTARI DENEY DÜZENEĞİ</text>\n  <text x="34" y="88" font-size="11" fill="#14532d">• A Kabı: Glikoz çözeltisi + Bira mayası + Ilık su (32 °C)</text>\n  <text x="34" y="112" font-size="11" fill="#14532d">• B Kabı: Gaz çıkış borusuyla bağlı Kireç suyu [Ca(OH)2]</text>\n  <text x="34" y="136" font-size="11" fill="#14532d">• Gözlem 1: A kabında glikoz azalır, etil alkol ve ısı artar</text>\n  <text x="34" y="160" font-size="11" fill="#14532d">• Gözlem 2: Çıkan CO2 gazı B kabındaki kireç suyunu bulandırır</text>\n  <text x="34" y="184" font-size="11" fill="#14532d">• Gözlem 3: Her iki kapta da pH değeri zamanla düşer</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#9333ea">KONTROLLÜ DENEY DEĞİŞKENLERİ</text>\n  <text x="370" y="88" font-size="11" fill="#581c87">• Bağımsız değişken: Araştırılan etken (örn. Sıcaklık)</text>\n  <text x="370" y="112" font-size="11" fill="#581c87">• Bağımlı değişken: Birim zamanda çıkan CO2 kabarcığı</text>\n  <text x="370" y="136" font-size="11" fill="#581c87">• Kontrol değişkenleri: Glikoz miktarı, su hacmi, maya</text>\n  <text x="370" y="160" font-size="11" fill="#581c87">• 60 °C üzerinde enzimler denatüre olur, tepkime durur</text>\n  <text x="370" y="184" font-size="11" fill="#581c87">• Alkol oranı %18\'i aşarsa maya hücreleri zehirlenir</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Termometredeki cıva seviyesinin yükselmesi hem solunumun hem fermantasyonun ekzergonik (ısı veren) olduğunu kanıtlar.</text>\n</svg>', 'b6': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">ENERJİ-METABOLİZMA İLİŞKİSİ VE BİYOTEKNOLOJİK ÖNEM</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#ea580c">CORI DÖNGÜSÜ (KAS - KARACİĞER)</text>\n  <text x="34" y="88" font-size="11" fill="#7c2d12">• Yoğun egzersizde çizgili kaslara O2 yetersiz kalır</text>\n  <text x="34" y="112" font-size="11" fill="#7c2d12">• Kaslar acil ATP için laktik asit fermantasyonu yapar</text>\n  <text x="34" y="136" font-size="11" fill="#7c2d12">• Biriken laktik asit kanla beyne giderek yorgunluk verir</text>\n  <text x="34" y="160" font-size="11" fill="#7c2d12">• Dinlenmede laktik asit kanla karaciğere taşınır</text>\n  <text x="34" y="184" font-size="11" fill="#7c2d12">• Karaciğerde pirüvata ve glikoza/glikojene dönüştürülür</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdfa" stroke="#0f766e" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f766e">ENDÜSTRİYEL FERMANTASYON</text>\n  <text x="370" y="88" font-size="11" fill="#134e4a">• Ekmek üretimi: Maya CO2 gazıyla hamuru kabartır</text>\n  <text x="370" y="112" font-size="11" fill="#134e4a">• Yoğurt, kefir ve peynir: Laktik asit bakterileri</text>\n  <text x="370" y="136" font-size="11" fill="#134e4a">• Turşu ve zeytin fermantasyonu: Asitlik zararlıları önler</text>\n  <text x="370" y="160" font-size="11" fill="#134e4a">• Biyoyakıt (biyoetanol): Bitkisel atıklardan etil alkol</text>\n  <text x="370" y="184" font-size="11" fill="#134e4a">• Bبازı bakterilerle sirke (asetik asit) üretimi</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Memelilerin olgun alyuvar hücreleri mitokondrilerini kaybettiği için yalnız laktik asit fermantasyonu yapar.</text>\n</svg>', '6': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">ENERJİ-METABOLİZMA İLİŞKİSİ VE BİYOTEKNOLOJİK ÖNEM</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#ea580c">CORI DÖNGÜSÜ (KAS - KARACİĞER)</text>\n  <text x="34" y="88" font-size="11" fill="#7c2d12">• Yoğun egzersizde çizgili kaslara O2 yetersiz kalır</text>\n  <text x="34" y="112" font-size="11" fill="#7c2d12">• Kaslar acil ATP için laktik asit fermantasyonu yapar</text>\n  <text x="34" y="136" font-size="11" fill="#7c2d12">• Biriken laktik asit kanla beyne giderek yorgunluk verir</text>\n  <text x="34" y="160" font-size="11" fill="#7c2d12">• Dinlenmede laktik asit kanla karaciğere taşınır</text>\n  <text x="34" y="184" font-size="11" fill="#7c2d12">• Karaciğerde pirüvata ve glikoza/glikojene dönüştürülür</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdfa" stroke="#0f766e" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f766e">ENDÜSTRİYEL FERMANTASYON</text>\n  <text x="370" y="88" font-size="11" fill="#134e4a">• Ekmek üretimi: Maya CO2 gazıyla hamuru kabartır</text>\n  <text x="370" y="112" font-size="11" fill="#134e4a">• Yoğurt, kefir ve peynir: Laktik asit bakterileri</text>\n  <text x="370" y="136" font-size="11" fill="#134e4a">• Turşu ve zeytin fermantasyonu: Asitlik zararlıları önler</text>\n  <text x="370" y="160" font-size="11" fill="#134e4a">• Biyoyakıt (biyoetanol): Bitkisel atıklardan etil alkol</text>\n  <text x="370" y="184" font-size="11" fill="#134e4a">• Bبازı bakterilerle sirke (asetik asit) üretimi</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Memelilerin olgun alyuvar hücreleri mitokondrilerini kaybettiği için yalnız laktik asit fermantasyonu yapar.</text>\n</svg>'}

def uygula(v):
    for i, b in enumerate(v.get('bolumler', []), 1):
        if f'b{i}' in GORSELLER:
            b['gorsel'] = GORSELLER[f'b{i}']
